#Requires -Version 5.1
[CmdletBinding()]
param([Parameter(Mandatory)][string]$StoreReceipt)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$expectedHost = 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
if (-not [Environment]::Is64BitProcess -or (Get-Process -Id $PID).Path -ine $expectedHost) { throw 'HOLD_UNAPPROVED_HOST' }
$env:PSModulePath = Join-Path $PSHOME 'Modules'
Import-Module (Join-Path $PSHOME 'Modules\Microsoft.PowerShell.Security\Microsoft.PowerShell.Security.psd1')
$sig = Get-AuthenticodeSignature -LiteralPath $expectedHost
if ($sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch '(^|,\s*)O=Microsoft Corporation(,|$)') { throw 'HOLD_HOST_SIGNATURE' }

$account = Get-LocalUser -Name 'windows'
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
try {
    $principal = [Security.Principal.WindowsPrincipal]::new($identity)
    if (-not $account.Enabled -or -not $account.SID.Equals($identity.User) -or
        -not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'HOLD_SIGNER_TOKEN' }
    $sid = $identity.User.Value
} finally { $identity.Dispose() }

if ($StoreReceipt -cnotmatch '^[a-f0-9]{16}:[a-f0-9]{32}:[a-f0-9]{64}$') { throw 'HOLD_STORE_RECEIPT_FORMAT' }
$base = 'F:\study\codex\Project-Limitless\Temp\DiscordUsageDiagnostics20261026'
$exe = Join-Path $base 'StagingVerifierRelease-3f674efb\candidate\Limitless.StagingVerifier.exe'
$test = Join-Path $base 'Worktree\Tools\DiscordV2\StagingDraft\Test-ApprovedSigningKey.ps1'
$exeSha = '145f3921e88ab2caba98afd4c5bb39eb7f9706aa6ad5e3fca5d5891f9f73adbb'
$testSha = 'ab57366eef3eefe1e74c6f50cebf440c815d88e6ef8aada2ffa66c616448b24f'
$thumb = '437423567AD4B703578F231E34A06592B38DB4EB'
$derSha = '7dba5310d6ded0035595e5e7ab8b8b73422f2925b49c633426995c322940672c'
# The independently verified SPKI is bound by the exact certificate DER SHA.
$spkiSha = '2a6d0a7d31e7642df209b6cbe12fa628500663f540eb6bd557cac2aca2d31f7c'
function Get-Sha($inputValue) {
    $hash = [Security.Cryptography.SHA256]::Create()
    try { [BitConverter]::ToString($hash.ComputeHash($inputValue)).Replace('-', '').ToLowerInvariant() }
    finally { $hash.Dispose() }
}
$embeddedAssembly = ''
$type = [Reflection.Assembly]::Load([Convert]::FromBase64String($embeddedAssembly)).GetType('LimitlessVerifierStorePreparation', $true)
$exeHandle = [IO.File]::Open($exe, 'Open', 'Read', 'Read')
try {
    $testHandle = [IO.File]::Open($test, 'Open', 'Read', 'Read')
    try {
        if ((Get-Sha $exeHandle) -cne $exeSha -or (Get-Sha $testHandle) -cne $testSha) { throw 'HOLD_ARTIFACT_SHA' }
        $cert = Get-Item -LiteralPath "Cert:\LocalMachine\My\$thumb"
        try {
            if ($cert.Thumbprint -cne $thumb -or (Get-Sha ([byte[]]$cert.RawData)) -cne $derSha) { throw 'HOLD_CERTIFICATE' }
        } finally { $cert.Dispose() }
        $now = [DateTimeOffset]::UtcNow
        $record = [ordered]@{
            Schema = 'LIMITLESS_SIGNING_ACCOUNT_DESIGNATION_V1'
            Approval = 'ISSUE66_SIGNER_DESIGNATION_RECORD_1'
            ApprovedBy = 'Project owner'
            Account = 'windows'
            AccountSid = $sid
            CertificateThumbprint = $thumb
            CertificateDerSha256 = $derSha
            RsaSpkiSha256 = $spkiSha
            CandidatePath = $exe
            CandidateSha256 = $exeSha
            KeyCheckScriptPath = $test
            KeyCheckScriptSha256 = $testSha
            RecordedUtc = $now.ToString('o')
            Scope = 'ACCOUNT_DESIGNATION_ONLY'
        }
        $body = [Text.UTF8Encoding]::new($false).GetBytes(($record | ConvertTo-Json -Compress))
        try {
            $receipt = $type::WriteDesignation($sid, $now, $now.AddMinutes(5), $StoreReceipt, $body)
            "DESIGNATION_CREATED_HANDLE_VERIFIED=$receipt"
        } catch {
            $cause = $_.Exception.GetBaseException()
            if ($cause -is [ComponentModel.Win32Exception]) { throw ("HOLD_NATIVE_ERROR_NO_RETRY_{0}" -f $cause.NativeErrorCode) }
            if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
            throw 'HOLD_RECORD_NO_RETRY'
        }
    } finally { $testHandle.Dispose() }
} finally { $exeHandle.Dispose() }
